const fs=require('fs'),zlib=require('zlib'),path=require('path');
const dir=__dirname,dec=s=>s.replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"').replace(/&apos;|&#39;/g,"'");
const attrs=s=>Object.fromEntries([...s.matchAll(/([\w]+)="([^"]*)"/g)].map(m=>[m[1],dec(m[2])]));
const strip=s=>s?.replace(/\^\d/g,'');
const categorySlugs={UniqueWeapon:'unique-weapons',UniqueArmour:'unique-armours',UniqueAccessory:'unique-accessories',UniqueFlask:'unique-flasks',UniqueJewel:'unique-jewels',ForbiddenJewel:'forbidden-jewels',UniqueTincture:'unique-tinctures',SkillGem:'skill-gems'};
const modDependent=new Set(["Watcher's Eye",'Sublime Vision','Lethal Pride','Brutal Restraint','Elegant Hubris','Militant Faith','Glorious Vanity','Forbidden Flesh','Forbidden Flame','The Balance of Terror','That Which Was Taken','The Light of Meaning','Impossible Escape']);
function activeItemText(text){let selected=+(text.match(/Selected Variant: (\d+)/)||[])[1];return text.split('\n').filter(l=>{let v=l.match(/\{variant:([^}]+)\}/);return !v||!selected||v[1].split(',').map(Number).includes(selected);}).filter(l=>!/^Variant:|^Selected Variant:|^<ModRange/.test(l)).map(l=>l.replace(/\{[^}]+\}/g,'')).join('\n');}
const initial=[
['shrapnel-nonmb','https://pobb.in/fw66mh2PgIPK'],['shrapnel-mb','https://pobb.in/nwxzb0uRh2Bz'],['shrapnel-minmax','https://pobb.in/IVpwp0NTTrme'],['ea-hit','https://pobb.in/zY5__MKcIUfb'],['poison-srs','https://pobb.in/7_6IS6EVRZfT'],['tornado','https://pobb.in/8kdqvrLk_OEi'],['toxic-rain','https://pobb.in/NlUa8ZnB3YGK'],['mamba','https://pobb.in/u/thedeathbeam%237125/pf-mamba-viper-strike']];
async function get(url){let r=await fetch(url,{headers:{'User-Agent':'PoE-Build-Research/1.0 personal research (no automatic polling)'},signal:AbortSignal.timeout(20000)});if(!r.ok)throw Error(r.status+' '+url);return r.json();}
async function run(){
 let leagues=await get('https://poe.ninja/poe1/api/economy/leagues');fs.writeFileSync(path.join(dir,'ninja-leagues.json'),JSON.stringify(leagues,null,2));
 let cachePath=path.join(dir,'ninja-standard-economy.json');let economy;
 if(fs.existsSync(cachePath))economy=JSON.parse(fs.readFileSync(cachePath,'utf8'));
 else{economy={league:'Standard',checkedAt:new Date().toISOString(),categories:{}};for(const type of ['UniqueWeapon','UniqueArmour','UniqueAccessory','UniqueFlask','UniqueJewel','ForbiddenJewel','UniqueTincture','SkillGem']){economy.categories[type]=await get('https://poe.ninja/poe1/api/economy/stash/current/item/overview?league=Standard&type='+type);console.log(type,economy.categories[type].lines?.length);}fs.writeFileSync(cachePath,JSON.stringify(economy));}
 const named=new Map();for(const [category,data]of Object.entries(economy.categories))for(const l of data.lines||[]){let a=named.get(l.name)||[];a.push({...l,category});named.set(l.name,a);}
 const incrementalPath=process.argv[2];let inputs=incrementalPath?JSON.parse(fs.readFileSync(incrementalPath,'utf8')):initial;if(!incrementalPath&&fs.existsSync(path.join(dir,'extra-pobs.json')))inputs.push(...JSON.parse(fs.readFileSync(path.join(dir,'extra-pobs.json'),'utf8')));
 const builds=[];
 for(const[id,url]of inputs){try{
  const cacheDir=path.join(dir,'pob-cache');fs.mkdirSync(cacheDir,{recursive:true});let xml,xmlPath=path.join(cacheDir,id+'.xml');const originalXmlPath=path.join(dir,id+'.xml');if(fs.existsSync(xmlPath))xml=fs.readFileSync(xmlPath,'utf8');else if(fs.existsSync(originalXmlPath))xml=fs.readFileSync(originalXmlPath,'utf8');else{const r=await fetch(url+'/raw',{signal:AbortSignal.timeout(20000)});if(!r.ok)throw Error('PoB '+r.status);let raw=(await r.text()).trim();xml=zlib.inflateSync(Buffer.from(raw.replace(/-/g,'+').replace(/_/g,'/'),'base64')).toString();fs.writeFileSync(xmlPath,xml);}
  const items=new Map([...xml.matchAll(/<Item id="(\d+)"[^>]*>([\s\S]*?)<\/Item>/g)].map(m=>{let text=dec(m[2]).trim(),lines=text.split('\n').map(l=>l.trim()),rarity=lines[0].replace('Rarity: ','');return[+m[1],{id:+m[1],rarity,name:lines[1],base:/UNIQUE|RELIC|RARE/.test(rarity)?lines[2]:lines[1],text}];}));
  const specs=[...xml.matchAll(/<Spec\b([^>]*)>([\s\S]*?)<\/Spec>/g)].map(m=>({attributes:attrs(m[1]),sockets:[...m[2].matchAll(/<Socket\b([^>]*)\/>/g)].map(s=>attrs(s[1]))}));
  const sets=[...xml.matchAll(/<ItemSet\b([^>]*)>([\s\S]*?)<\/ItemSet>/g)].map((m,index)=>{let a=attrs(m[1]);const actor=/^(?:AG\b|Min Max AG|Animate Guardian)/i.test(strip(a.title)||'')?'Animate Guardian':'Player';let refs=(a.title?.match(/\{([^}]+)\}/)||[])[1]?.split(',').map(Number);let refSpecs=refs?specs.filter(s=>refs.some(n=>(s.attributes.title||'').includes('{'+n+'}'))):[];let spec=actor==='Player'?(specs.find(s=>s.attributes.title===a.title)||refSpecs.at(-1)||(id==='ea-hit'?specs.find(s=>/ENDGAME FULL BUILD/.test(s.attributes.title||'')):null)||(specs.length===1?specs[0]:undefined)):undefined;let slots=[...m[2].matchAll(/<Slot\b([^>]*)\/>/g)].map(s=>attrs(s[1])).filter(s=>+s.itemId&&!/Swap/.test(s.name));for(const s of spec?.sockets||[])if(+s.itemId)slots.push({name:'Jewel '+s.nodeId,itemId:s.itemId});
   let rows=slots.map(s=>{let item=items.get(+s.itemId);if(!item)return{slot:s.name,status:'missing_item_in_pob'};let {text,...out}=item;text=activeItemText(text);let row={slot:s.name,...out,requirements:text.split('\n').filter(l=>!/^Implicits|^Variant|^Selected|^Item Level|^LevelReq|^Unique ID|^Crafted|^Quality|^Rarity|^Sockets|^Prefix|^Suffix|^League/.test(l)).slice(3),status:'unpriced',reason:'poe.ninja не оценивает точные редкие/магические модификаторы'};
    if(/UNIQUE|RELIC/.test(item.rarity)){let candidates=(named.get(item.name)||[]).filter(l=>!l.baseType||l.baseType===item.base);let corrupt=/\nCorrupted\s*(?:\n|$)/.test(text);let link=(text.match(/Sockets: ([^\n]+)/)||[])[1];let links=link?Math.max(...link.split(' ').map(g=>g.split('-').length)):0;candidates=candidates.filter(l=>Boolean(l.corrupted)===corrupt&&(!links||links<5||l.links===links));
     if(item.name==='Voices'){let n=(text.match(/Adds (\d+) Small Passive/)||[])[1];if(n)candidates=candidates.filter(l=>(n==='1'&&!l.variant)||l.variant===n+' passives');}
     if(item.name==='Mageblood'){let n=(text.match(/Leftmost (\d+) Magic Utility Flasks/)||[])[1];if(n)candidates=candidates.filter(l=>l.variant===n+' Flasks');}
     row.candidates=candidates.map(l=>({name:l.name,variant:l.variant||null,links:l.links||null,corrupted:Boolean(l.corrupted),chaos:l.chaosValue,divine:l.divineValue,count:l.count,listingCount:l.listingCount,category:l.category,url:'https://poe.ninja/poe1/economy/standard/'+categorySlugs[l.category]+'/'+l.detailsId}));
     if(candidates.length===1&&!modDependent.has(item.name)){row.status='unique_reference';row.reference=row.candidates[0];row.reason='Ориентир категории poe.ninja; роллы, implicit, corruption и legacy-вариант могут отличаться от PoB. Не точная цена вещи.';}else row.reason=modDependent.has(item.name)?'Цена зависит от конкретного модификатора/seed/набора свойств; общий ориентир не включён в subtotal':candidates.length?'Несколько вариантов poe.ninja: нельзя выбрать без проверки модификаторов':'Нет совпавшей категории poe.ninja для этого предмета/линков/corruption';
    }return row;});
   return{id:a.id,title:strip(a.title)||'Основной комплект',actor,treeTitle:strip(spec?.attributes.title)||null,treeVersion:spec?.attributes.treeVersion,jewelsIncluded:Boolean(spec),items:rows,uniqueReferenceSubtotalDivine:rows.reduce((v,r)=>v+(r.reference?.divine||0),0),referencePricedSlots:rows.filter(r=>r.status==='unique_reference').length,unpricedSlots:rows.filter(r=>r.status!=='unique_reference').length,totalBuildPrice:null};
  });
  builds.push({id,url,sets});console.log(id,sets.length,'sets');
 }catch(e){builds.push({id,url,error:String(e)});console.log(id,String(e));}}
 const auditPath=path.join(dir,'pricing-audit.json');let outputBuilds=builds;if(incrementalPath&&fs.existsSync(auditPath)){let old=JSON.parse(fs.readFileSync(auditPath,'utf8')).builds;let merged=new Map(old.map(b=>[b.id,b]));for(const b of builds)merged.set(b.id,b);outputBuilds=[...merged.values()];}
 const out={checkedAt:economy.checkedAt,clientDate:'2026-11-12',league:'Standard',availableLeagues:leagues,source:'https://poe.ninja/docs/api',method:'Public supported stash economy overview; raw author PoBs. No rare-item valuation or future league budget. Unique sums are reference-category subtotals, never a complete build price.',builds:outputBuilds};
 fs.writeFileSync(path.join(dir,'pricing-audit.json'),JSON.stringify(out,null,2));console.log('DONE',builds.length);
}run().catch(e=>{console.error(e);process.exitCode=1});
